INSERT INTO `space_versions` (`version`, `title`, `summary`, `created_at`) VALUES ('v135', '菜单与最近聊天分界线直接拖动、豆包图片走公开图床中转', '侧边栏里菜单栏与最近聊天栏之间的分界线改为常驻可见（带拖动手柄）：不用先开「窗口大小」开关、不用长按，直接按住上下拖动就能调整上下两个窗口的比例，松手自动保存，拖好的高度下次打开仍在。豆包看图新增公开图床中转：给豆包发图片时，图片先匿名上传到公开图床（依次尝试 uguu、Litterbox、Catbox），拿到的公开直链随消息一起发给豆包、并为这次发送强制打开联网搜索，让豆包自己打开链接读图后回复；三个图床都失败时如实报出各自的失败原因、不改走纯文字假装发过。注意：经图床中转的图片凭链接可公开访问，临时图床的文件会自动删除。', strftime('%s','now') * 1000);
